{
  "interpretation": {
    "name": "TightenF25AtSt1WithNR7",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten the fasteners of forklift variant F25 at station st1 using nutrunner NR7, then evaluate and record the result so the blocked unit can proceed.",
    "constraints": [
      "NR7 must be reserved before use, and the lease must be renewed before every physical use",
      "NR7 must be transported to the station by agvexecutor before configure-tool and tighten-fasteners",
      "The tightening program must come only from get-program and must not appear as literal values in the Recipe",
      "The tightening must be evaluated against its program and recorded for traceability",
      "The reservation must be released after use"
    ],
    "preference": "Return NR7 to the crib after use so it is available to other lines.",
    "priority": "high",
    "horizon": "Immediate, single execution",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-f25-st1-nr7",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "MoveToStation",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "MoveToStation",
        "next": "Tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "Tighten",
        "next": "Quality",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten"], "dep": ["program", "reserve", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Quality",
        "next": "Finish",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "Finish",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
